/* UI for Nga Anh's rabbit trail. Recordings stay in memory on this device. */
(() => {
 'use strict';
 const GC=window.HaloGameCore;
 let app,route={},session=null,lastResult=null,selectedChapter=0,showAll=false,autoTimer=null,recorder=null,stream=null,audioURL=null,recordingBusy=false,recordingToken=0,spokenSample=false,order=[],assisted=false,jumpToRabbit=false;
 const $=s=>document.querySelector(s),E=s=>app.C.escape(s);
 let lastFeedbackKey='';
 function coaching(q,answer){
  let streak=0;if(answer?.correct&&q.skill!=='speaking'&&session){for(let i=session.index;i>=0;i--){const previous=session.questions[i],a=session.answers[previous.id];if(previous.skill==='speaking')continue;if(!a?.correct)break;streak++;}}
  return window.HaloGameFeedback.choose({correct:answer?.correct===true,skill:q.skill,streak,index:session?.index||0,stage:session?.stage||1});
 }
 function renderCoaching(q,answer){const message=coaching(q,answer);return `<div class="game-feedback coaching-panel ${answer.correct===false?'needs-review':q.skill==='speaking'?'practice-feedback':'is-correct'}" role="status" tabindex="-1"><div class="coaching-head"><span class="feedback-emotion" aria-hidden="true">${message.symbol}</span><div><span class="feedback-status">${E(message.status)}</span><strong>${E(message.title)}</strong></div>${message.streak>=2?`<span class="answer-streak">✦ ${message.streak} câu đúng liên tiếp</span>`:''}</div><p class="coaching-copy">${E(message.body)}</p><details class="answer-explanation" open><summary>${q.skill==='speaking'?'Ghi chú tự luyện nói':'Đáp án & cách ghi nhớ'}</summary><p>${answer.correct===false?`Đáp án: <b>${E(q.answer)}</b><br>`:''}${E(q.explanation)}</p></details>${answer.assisted?'<small class="feedback-coach-note">Phần nghe được thực hiện ở chế độ hỗ trợ bằng văn bản.</small>':''}</div>`;}
 const game=()=>app.progress.game||(app.progress.game=GC.blank());
 const btn=(text,action,extra='',classes='')=>`<button class="button ${classes}" data-action="g-${action}" ${extra}>${text}</button>`;
 const link=(stage,view='game')=>`#/${view}/${Math.ceil(stage/20)}/${stage}`;
 const day=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const skillIcon={vocab:'字',grammar:'句',reading:'读',listening:'听',writing:'写',speaking:'说'};
 function bunny(extra=''){return `<svg class="bunny-svg ${extra}" viewBox="0 0 180 210" aria-hidden="true"><ellipse class="bunny-shadow" cx="90" cy="195" rx="49" ry="8" fill="#b864881a"/><g class="bunny-body"><g class="bunny-ear left"><path d="M54 81C27 33 37 6 52 9c15 3 19 38 21 66" fill="#fffafa" stroke="#965972" stroke-width="3"/><path d="M55 61c-13-28-13-40-8-42 6-2 12 17 15 42" fill="#f9bdd0"/></g><g class="bunny-ear right"><path d="M105 77c3-45 18-73 31-64 12 10 6 39-13 70" fill="#fffafa" stroke="#965972" stroke-width="3"/><path d="M117 64c9-30 15-41 19-38 4 4-3 24-11 43" fill="#f9bdd0"/></g><ellipse cx="91" cy="153" rx="39" ry="40" fill="#fffafa" stroke="#965972" stroke-width="3"/><ellipse cx="71" cy="188" rx="18" ry="10" fill="#fffafa" stroke="#965972" stroke-width="3"/><ellipse cx="111" cy="188" rx="18" ry="10" fill="#fffafa" stroke="#965972" stroke-width="3"/><ellipse cx="48" cy="148" rx="12" ry="20" transform="rotate(24 48 148)" fill="#fffafa" stroke="#965972" stroke-width="3"/><ellipse cx="133" cy="148" rx="12" ry="20" transform="rotate(-25 133 148)" fill="#fffafa" stroke="#965972" stroke-width="3"/><path d="M38 98c0-33 25-48 53-48s52 19 52 49c0 29-22 46-52 46s-53-17-53-47" fill="#fffafa" stroke="#965972" stroke-width="3"/><ellipse cx="57" cy="111" rx="12" ry="7" fill="#f4b2c9"/><ellipse cx="125" cy="111" rx="12" ry="7" fill="#f4b2c9"/><g class="bunny-eyes" fill="#704356"><ellipse cx="71" cy="98" rx="4" ry="6"/><ellipse cx="110" cy="98" rx="4" ry="6"/></g><path d="m87 111 5 3 5-3m-5 3v4m-6 1q6 5 12 0" fill="none" stroke="#965972" stroke-width="2.5" stroke-linecap="round"/><path d="M91 164c-15-12-21 5 0 17 21-12 15-29 0-17" fill="#e78bab"/><path d="m129 80 7 8 13-8-10-7" fill="#e68cab"/><circle cx="138" cy="80" r="3" fill="#fff1bd"/></g></svg>`;}
 function clearAuto(){clearTimeout(autoTimer);autoTimer=null;}
 function stopRecording(){recordingToken++;recordingBusy=false;if(recorder&&recorder.state!=='inactive')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;window.HaloMusic?.release('recording');}
 function cleanup(){clearAuto();stopRecording();window.HaloMusic?.cancelSpeech();if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null;}}
 function saveSession(){try{if(session)localStorage.setItem('halochina-game-session-v1',JSON.stringify(session));else localStorage.removeItem('halochina-game-session-v1');}catch{app.toast('Chưa lưu được lượt chơi. Hãy hoàn thành trước khi đóng trang.');}}
 function loadSession(){
  try{const s=JSON.parse(localStorage.getItem('halochina-game-session-v1')||'null');if(!s||!GC.clampStage(s.stage)||!Array.isArray(s.questions)||![12,16].includes(s.questions.length)||!Number.isInteger(s.index)||s.index<0||s.index>=s.questions.length||typeof s.answers!=='object'||!s.answers||GC.status(game(),s.stage)==='locked')return null;
   if(s.questions.some(q=>!q||typeof q.id!=='string'||!GC.SKILLS[q.skill]||!['choice','typing','order','speaking'].includes(q.type)||typeof q.answer!=='string'||typeof q.prompt!=='string'||q.type==='choice'&&(!Array.isArray(q.options)||q.options.length!==4||!q.options.includes(q.answer))||q.type==='order'&&(!Array.isArray(q.tokens)||q.tokens.length>80)))return null;return s;
  }catch{return null;}
 }
 function streak(){const dates=new Set(Object.keys(game().days).filter(k=>game().days[k]>0));let cursor=new Date(),count=0;const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(!dates.has(key(cursor)))cursor.setDate(cursor.getDate()-1);while(dates.has(key(cursor))){count++;cursor.setDate(cursor.getDate()-1);}return count;}
 function renderMap(r){route=r;const g=game(),s=GC.stats(g),currentInfo=GC.stageInfo(s.current,app.V,app.L);if(!selectedChapter)selectedChapter=currentInfo.hsk;const chapters=showAll?[1,2,3,4,5,6]:[selectedChapter],active=loadSession(),daily=g.days[day()]||0;
  return `<section class="game-hero"><div><div class="pink-eyebrow">DÀNH RIÊNG CHO NGA ANH</div><h1>Một bước nhỏ,<br>một chút <em>giỏi hơn.</em></h1><p>Cùng Thỏ Mây đi qua 120 cấp độ.<br>Học, chơi và gom những điều mới mỗi ngày.</p><div class="actions-inline">${btn(active?'Tiếp tục lượt chơi':'Đi cùng Thỏ Mây →',active?'resume':'brief',active?'':`data-stage="${s.current}"`)}<span class="game-hero-note">${s.completed===120?'Bạn đã chinh phục cả hành trình!':`Thỏ đang chờ ở cấp ${s.current}`}</span></div></div><div class="game-hero-rabbit">${bunny()}<span class="rabbit-speech">${s.completed?'Giỏi lắm, Nga Anh!':'Mình cùng bắt đầu nhé!'} ♡</span><span class="rabbit-flower f1">✿</span><span class="rabbit-flower f2">✦</span></div></section>
  <div class="journey-stats"><div><span class="journey-stat-icon">🌷</span><p><strong>${s.completed}<small> / 120</small></strong><span>Cấp đã chinh phục</span></p></div><div><span class="journey-stat-icon">✦</span><p><strong>${s.xp}</strong><span>Điểm kinh nghiệm</span></p></div><div><span class="journey-stat-icon">★</span><p><strong>${s.stars}<small> / 360</small></strong><span>Ngôi sao của bạn</span></p></div><div><span class="journey-stat-icon">♡</span><p><strong>${streak()}<small> ngày</small></strong><span>Chuỗi ngày chơi</span></p></div></div>
  ${active?`<div class="game-resume"><span class="status-badge in-progress">Đang chơi</span><span>Cấp ${active.stage} · ${Object.keys(active.answers).length}/${active.questions.length} thử thách đã làm</span>${btn('Tiếp tục','resume','','small ghost')}${btn('Bỏ lượt này','ask-discard','','small text-button')}</div>`:''}
  <div class="journey-layout"><section class="journey-main" aria-label="Đường đi 120 cấp"><div class="journey-heading"><div><span class="pink-eyebrow">HÀNH TRÌNH CỦA THỎ MÂY</span><h2>120 cấp độ, vô vàn điều hay</h2></div><label class="checkbox-label"><input id="game-show-all" type="checkbox" ${showAll?'checked':''}> Xem cả 120 cấp</label></div><div class="world-tabs" role="group" aria-label="Chọn thế giới HSK">${[1,2,3,4,5,6].map(n=>`<button data-action="g-world" data-world="${n}" class="world-tab ${selectedChapter===n&&!showAll?'selected':''}" aria-pressed="${selectedChapter===n&&!showAll}"><span>${GC.WORLDS[n].symbol}</span> HSK${n}<small>${(n-1)*20+1}–${n*20}</small></button>`).join('')}</div><div class="map-legend"><span><i class="legend-dot ready"></i> Sẵn sàng</span><span><i class="legend-dot passed"></i> Đã thắng</span><span><i class="legend-dot locked"></i> Chưa mở</span></div>${chapters.map(n=>renderWorld(n,g,s)).join('')}</section>
  <aside class="journey-aside"><section class="game-panel rabbit-passport"><div class="passport-avatar">${bunny()}</div><span class="pink-eyebrow">BẠN ĐỒNG HÀNH CỦA NGA ANH</span><h3>Thỏ Mây</h3><p>${s.completed===120?'Nhà thám hiểm của cả sáu thế giới.':`Đang ở ${E(currentInfo.world.name.toLowerCase())}`}</p><div class="passport-position"><span>Vị trí hiện tại</span><strong>Cấp ${s.current} <small>· HSK${currentInfo.hsk}</small></strong></div><div class="progress-track"><i style="width:${s.completed/120*100}%"></i></div><span class="subtle">${Math.round(s.completed/120*100)}% hành trình hoàn thành</span></section><section class="game-panel"><h3>Một chút mỗi ngày ♡</h3><p>Chinh phục một cấp để đạt mục tiêu <strong>30 XP</strong>.</p><div class="daily-xp"><strong>${daily}</strong><span>/ 30 XP hôm nay</span></div><div class="progress-track"><i style="width:${Math.min(100,daily/30*100)}%"></i></div><span class="status-badge ${daily>=30?'complete':'ready'}">${daily>=30?'✓ Hoàn thành mục tiêu':'Cùng gom thêm một chút nhé'}</span></section><section class="game-panel"><h3>Chơi để nhớ lâu hơn</h3><ul class="game-rules"><li>20 cấp cho mỗi HSK</li><li>Đủ 6 kỹ năng trong mỗi lượt</li><li>Mốc ôn tập sau mỗi 5 cấp</li><li>Đúng ≥80% và mỗi kỹ năng đạt ≥50%</li><li>Đọc to & tự xác nhận phần nói</li><li>Thắng để mở cấp tiếp theo</li></ul><a class="text-link" href="#/game-guide/1">Xem cách chơi & nguồn tham khảo ↗</a></section></aside></div>`;
 }
 function renderWorld(hsk,g,s){const first=(hsk-1)*20+1,world=GC.WORLDS[hsk],done=Array.from({length:20},(_,i)=>g.cleared[first+i]).filter(Boolean).length,positions=[50,65,73,65,50,35,27,35];
  const points=Array.from({length:20},(_,i)=>({x:positions[i%8]*10,y:108*i+120}));let path=`M ${points[0].x} ${points[0].y}`;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],mid=(a.y+b.y)/2;path+=` C ${a.x} ${mid}, ${b.x} ${mid}, ${b.x} ${b.y}`;}
  return `<section class="world-section" id="world-${hsk}" style="--world-color:${world.color}"><header class="world-banner"><span class="world-emoji">${world.symbol}</span><div><span>THẾ GIỚI ${hsk} · HSK${hsk}</span><h3>${world.name}</h3><p>${world.subtitle}</p></div><strong>${done}<small>/20</small></strong></header><div class="path-canvas" style="height:2330px"><svg class="trail-line" viewBox="0 0 1000 2330" preserveAspectRatio="none" aria-hidden="true"><path d="${path}"/></svg><div class="path-decoration blossom">✿</div><div class="path-decoration carrot">🥕</div><div class="path-decoration cloud">☁</div><div class="path-decoration blossom second">✧</div>${points.map((p,i)=>{const stage=first+i,info=GC.stageInfo(stage,app.V,app.L),status=GC.status(g,stage),current=stage===s.current;return `<div class="trail-stop ${status} ${current?'current-stop':''}" style="left:${p.x/10}%;top:${p.y-38}px">${current?`<span class="rabbit-marker" aria-label="Thỏ Mây ở cấp ${stage}">${bunny()}</span>`:''}<button class="stage-node ${info.checkpoint?'checkpoint':''}" data-action="g-brief" data-stage="${stage}" data-status="${status}" aria-label="Cấp ${stage}: ${E(info.title)}. ${status==='locked'?'Chưa mở':status==='cleared'?'Đã chinh phục':'Sẵn sàng chơi'}" ${current?'aria-current="step"':''}><span class="node-symbol">${status==='locked'?lockSVG():status==='cleared'?'✓':info.final?'♛':info.checkpoint?'★':'▶'}</span><span class="node-level">${stage}</span></button><span class="stage-caption">Cấp ${stage}${info.final?' · Vương miện':info.checkpoint?' · Ôn tập':''}</span>${status==='cleared'?`<span class="stage-stars" aria-label="${g.cleared[stage].stars} sao">${'★'.repeat(g.cleared[stage].stars)}<span>${'☆'.repeat(3-g.cleared[stage].stars)}</span></span>`:current?'<span class="stage-ready-label">THỎ ĐANG Ở ĐÂY</span>':'<span class="stage-lock-label">Chưa mở</span>'}</div>`;}).join('')}<div class="world-finish"><span>🎀</span> ${done===20?'Đã chinh phục thế giới này!':`Hẹn Nga Anh ở cột mốc ${hsk*20}`}</div></div></section>`;
 }
 function lockSVG(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/><path d="M12 14v3"/></svg>';}
 function brief(stage){stage=GC.clampStage(stage);if(!stage)return;const info=GC.stageInfo(stage,app.V,app.L),state=GC.status(game(),stage),active=loadSession();
  if(state==='locked'){app.openDialog(`Cấp ${stage} chưa mở`, `<div class="brief-bunny">${bunny()}</div><span class="status-badge locked">Chưa mở khóa</span><p class="dialog-copy">Hoàn thành cấp ${stage-1} để mở cấp này. Thỏ Mây đang đợi Nga Anh ở cấp ${GC.unlocked(game())}.</p>${btn('Đến chỗ Thỏ Mây','go-current')}`);return;}
  app.openDialog(`Cấp ${stage} · HSK${info.hsk}`,`<div class="brief-bunny">${bunny()}</div><div class="brief-heading"><span class="status-badge ${state==='cleared'?'complete':'ready'}">${state==='cleared'?'✓ Đã chinh phục':'Sẵn sàng chơi'}</span>${info.checkpoint?'<span class="status-badge checkpoint-badge">★ Mốc ôn tập</span>':''}<h3>${E(info.title)}</h3><p>${E(info.goal)}</p></div><div class="skill-pills">${Object.entries(GC.SKILLS).map(([id,label])=>`<span><b>${skillIcon[id]}</b>${label}</span>`).join('')}</div><div class="brief-facts"><span><strong>${info.count}</strong> thử thách</span><span><strong>≥80%</strong> để thắng</span><span><strong>3</strong> sao tối đa</span></div><p class="subtle">Phải làm phần nói và đạt ít nhất 50% ở từng kỹ năng có chấm điểm. Phần nói là tự đánh giá, có lựa chọn không dùng micro.</p>${active?`<div class="notice">Bạn đang có lượt chơi ở cấp ${active.stage}. Hãy tiếp tục hoặc bỏ lượt đó trước.</div><div class="actions-inline">${btn('Làm tiếp','resume')}${btn('Bỏ lượt đang dở','ask-discard','','ghost')}</div>`:btn(state==='cleared'?'Chơi lại để ôn tập':'Bắt đầu cùng Thỏ Mây →','start',`data-stage="${stage}"`)}<a class="brief-lesson-link" href="#/lesson/${info.hsk}/${info.lesson.id}">Ôn bài “${E(info.lesson.title)}” trước ↗</a>`);
 }
 function start(stage){stage=GC.clampStage(stage);if(!stage||GC.status(game(),stage)==='locked'){app.toast('Hãy hoàn thành cấp trước để mở khóa.');return;}if(loadSession()){app.toast('Bạn đang có một lượt chơi chưa xong.');return;}
  cleanup();window.HaloMusic?.startGame();session={version:1,stage,questions:GC.buildQuestions(stage,app.V,app.L,app.C),answers:{},index:0,startedAt:Date.now(),phase:'playing'};order=[];spokenSample=false;assisted=false;saveSession();$('#reader-dialog').close();location.hash=link(stage);
 }
 function ensureSession(r){if(!session)session=loadSession();const wanted=GC.clampStage(r.id);if(!wanted||GC.status(game(),wanted)==='locked')return false;return session?.stage===wanted;}
 function renderPlay(r){route=r;const wanted=GC.clampStage(r.id);if(!ensureSession(r))return `<div class="game-empty"><div class="brief-bunny">${bunny()}</div><h1>${wanted&&GC.status(game(),wanted)==='locked'?'Cấp này chưa mở khóa':'Chưa có lượt chơi ở cấp này'}</h1><p>Thỏ Mây đang ở cấp ${GC.unlocked(game())}. Bạn có thể chọn cấp đã mở trên bản đồ.</p><a class="button" href="#/games/1">Quay lại bản đồ →</a></div>`;
  const s=session,q=s.questions[s.index],answer=s.answers[q.id],sc=GC.evaluate(s),wrong=Object.values(s.answers).filter(a=>a.correct===false).length,info=GC.stageInfo(s.stage,app.V,app.L);
  return `<div class="play-top"><a class="back-link" href="#/games/${info.hsk}">← Bản đồ của Thỏ Mây</a><span class="status-badge ${answer?'reviewing':'in-progress'}">${answer?'Đã trả lời · xem giải thích':'Đang chơi'}</span></div><div class="play-heading"><div><span class="pink-eyebrow">HSK${info.hsk} · CẤP ${s.stage} / 120</span><h1>${E(info.title)}</h1></div><div class="game-hearts" aria-label="${Math.max(0,3-wrong)} trái tim còn lại"><span>${'♥'.repeat(Math.max(0,3-wrong))}<i>${'♡'.repeat(Math.min(3,wrong))}</i></span><small>${wrong>=3?'Cứ luyện hết lượt nhé':'Cùng giữ nhịp thật tốt'}</small></div></div><div class="play-progress"><div class="progress-track"><i style="width:${Object.keys(s.answers).length/s.questions.length*100}%"></i></div><span>${Object.keys(s.answers).length}/${s.questions.length}</span></div><div class="game-play-layout"><section class="game-panel challenge-card"><div class="challenge-meta"><span class="skill-token">${skillIcon[q.skill]}</span><span>${GC.SKILLS[q.skill]} <small>· ${E(q.label)}</small></span><span class="challenge-count">${s.index+1} / ${s.questions.length}</span></div><h2 class="challenge-prompt">${E(q.prompt)}</h2>${q.passage?`<div class="game-passage" lang="zh">${E(q.passage)}</div>`:''}${q.hint?`<p class="pinyin game-hint">${E(q.hint)}</p>`:''}
  ${q.type==='choice'?`${q.speak?`<div class="listen-row">${btn(app.icon('sound')+' Nghe câu mẫu','listen','','ghost')}<span>Giọng đọc tổng hợp · nghe lại tùy ý</span></div><div id="listening-support"></div>`:''}<div class="choices">${q.options.map((option,i)=>`<button class="choice ${answer?.text===option?'chosen':''} ${answer&&option===q.answer?'correct':''} ${answer?.text===option&&!answer.correct?'incorrect':''}" data-action="g-choice" data-option="${E(option)}" ${answer?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${E(option)}</button>`).join('')}</div>`:''}
  ${q.type==='typing'?`<form id="game-write-form"><label class="input-label" for="game-typed">Câu trả lời bằng chữ Hán</label><input id="game-typed" type="text" autocomplete="off" spellcheck="false" lang="zh" placeholder="Gõ bằng bàn phím tiếng Trung…" value="${E(answer?.text||'')}" ${answer?'disabled':''}><p class="subtle">Có thể dùng bộ gõ Pinyin của điện thoại hoặc máy tính.</p>${answer?'':btn('Kiểm tra câu trả lời','check-typing')}</form>`:''}
  ${q.type==='order'?`<p class="subtle">Chọn các mảnh từ theo thứ tự; bấm vào mảnh đã chọn để đưa trở lại.</p><div class="sentence-tray" id="sentence-tray">${renderOrderTray(q,answer)}</div><div class="token-bank">${q.tokens.map(t=>`<button class="word-token" data-action="g-token" data-token="${t.id}" ${answer||order.includes(t.id)?'disabled':''}>${E(t.text)}</button>`).join('')}</div>${answer?'':btn('Kiểm tra câu đã ghép','check-order')}`:''}
  ${q.type==='speaking'?`<div class="speaking-box"><p>${E(q.explanation)}</p><div class="actions-inline">${btn(app.icon('sound')+' Nghe mẫu','listen','','ghost')}${btn('● Thu âm','record','','ghost')}${btn('■ Dừng thu','stop-record','disabled','ghost')}</div><div id="recording-status" class="recording-status" role="status">Micro chỉ bật khi bạn bấm Thu âm. Bản ghi ở trên thiết bị và không được tải lên.</div><div id="recording-preview"></div><details class="speaking-alternative"><summary>Không dùng micro?</summary><p>Nghe mẫu rồi đọc to thành tiếng ít nhất hai lần. Tự đối chiếu thanh điệu và nhịp câu. Bạn vẫn có thể xác nhận đã luyện nói mà không thu âm.</p></details><label class="checkbox-label speaking-confirm"><input id="spoken-confirm" type="checkbox" ${answer?'checked disabled':''}> Tôi đã đọc to và tự đối chiếu với câu mẫu.</label>${answer?'':btn('Xác nhận đã luyện nói','confirm-spoken')}</div>`:''}
  ${answer?renderCoaching(q,answer):''}<div class="challenge-footer"><span>${sc.correct}/${sc.total} câu tính điểm đã đúng</span>${answer?btn(s.index===s.questions.length-1?'Xem kết quả ✦':'Tiếp tục →','next'):'<span class="subtle">Chọn hoặc nhập câu trả lời để tiếp tục</span>'}</div></section><aside class="play-companion game-panel ${answer?'companion-'+coaching(q,answer).tone:''}"><div class="play-bunny">${bunny(answer?.correct?'happy':'')}</div><h3>${answer?E(coaching(q,answer).title):'Thỏ Mây ở đây với bạn.'}</h3><p>${answer?E(coaching(q,answer).body):'Mình đi chậm thôi, miễn là không bỏ cuộc.'}</p><div class="game-skill-checks">${Object.entries(GC.SKILLS).map(([k,name])=>{const qs=s.questions.filter(x=>x.skill===k),done=qs.filter(x=>s.answers[x.id]).length;return `<span class="${done===qs.length?'done':''}"><i>${done===qs.length?'✓':'○'}</i>${name}<small>${done}/${qs.length}</small></span>`;}).join('')}</div><label class="checkbox-label auto-next"><input id="game-auto-next" type="checkbox" ${game().autoAdvance?'checked':''}> Tự chuyển câu sau 3 giây</label><p class="subtle">Chỉ tự chuyển sau khi trả lời; tắt để đọc lời giải lâu hơn.</p></aside></div>`;
 }
 function renderOrderTray(q,answer){if(answer)return `<span>${E(answer.text)}</span>`;if(!order.length)return '<span class="tray-placeholder">Câu của Nga Anh sẽ ở đây…</span>';return order.map(id=>`<button class="word-token selected" data-action="g-untoken" data-token="${id}">${E(q.tokens.find(t=>t.id===id)?.text||'')}</button>`).join('');}
 function accept(text,extra={}){if(!session)return;const q=session.questions[session.index];if(session.answers[q.id])return;if(q.type==='speaking'&&!extra.practiced)return;if(q.skill==='listening'&&!spokenSample){app.toast('Nga Anh bấm Nghe câu mẫu trước khi trả lời nhé.');return;}
  const correct=q.type==='speaking'?true:q.type==='choice'?text===q.answer:GC.textKey(text)===GC.textKey(q.answer);session.answers[q.id]={text,correct,...extra};session.phase='feedback';saveSession();app.render();}
 function next(){clearAuto();if(!session)return;if(!session.answers[session.questions[session.index].id])return;cleanup();if(session.index===session.questions.length-1){finish();return;}session.index++;session.phase='playing';order=[];spokenSample=false;assisted=false;saveSession();app.render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 function finish(){const scored=GC.award(game(),session,day());app.progress.game=scored.game;app.persist();lastResult={...session,...scored.score,gained:scored.gained,finishedAt:Date.now()};try{localStorage.setItem('halochina-game-result-v1',JSON.stringify(lastResult));}catch{}const stage=session.stage;session=null;saveSession();selectedChapter=Math.ceil(GC.unlocked(game())/20);location.hash=link(stage,'game-result');}
 function result(){if(lastResult)return lastResult;try{const s=JSON.parse(localStorage.getItem('halochina-game-result-v1')||'null');return s&&GC.clampStage(s.stage)&&Array.isArray(s.questions)&&s.questions.length<=16?s:null;}catch{return null;}}
 function renderResult(r){route=r;const s=result();if(!s||String(s.stage)!==r.id)return '<div class="game-empty"><h1>Chưa có kết quả của cấp này</h1><a class="button" href="#/games/1">Về bản đồ</a></div>';const current=GC.unlocked(game()),weak=Object.entries(s.skills).filter(([k,v])=>k!=='speaking'&&v.correct/v.total<.5).map(([k])=>GC.SKILLS[k]);
  return `<section class="game-result ${s.passed?'victory':'try-again'}"><div class="result-confetti" aria-hidden="true">${s.passed?Array.from({length:16},(_,i)=>`<i style="--i:${i}">${i%3===0?'✦':i%3===1?'♡':'✿'}</i>`).join(''):''}</div><span class="status-badge ${s.passed?'complete':'reviewing'}">${s.passed?'✓ ĐÃ CHINH PHỤC':'CẦN ÔN THÊM'}</span><div class="result-rabbit">${bunny(s.passed?'happy':'')}</div><div class="victory-stars" aria-label="${s.stars} sao">${'★'.repeat(s.stars)}<span>${'☆'.repeat(3-s.stars)}</span></div><h1>${s.passed?'Nga Anh giỏi quá!':'Mình thử lại nhé, Nga Anh.'}</h1><p>${s.passed?(s.stage===120?'Bạn và Thỏ Mây đã hoàn thành cả 120 cấp!':`Cấp ${s.stage} đã hoàn thành. ${current>s.stage?`Cấp ${s.stage+1} đã mở khóa.`:'Bạn có thể chơi lại để ôn tập.'}`):`Cần đúng ít nhất 80%, đạt 50% ở từng kỹ năng có chấm điểm và hoàn thành phần nói.${weak.length?` Cùng ôn lại: ${weak.join(', ')}.`:''}`}</p><div class="result-metrics"><div><strong>${s.accuracy}%</strong><span>Độ chính xác</span></div><div><strong>+${s.gained}</strong><span>XP vừa nhận</span></div><div><strong>${s.correct}/${s.total}</strong><span>Câu đúng</span></div></div>${s.assisted?'<div class="notice">Bạn đã dùng văn bản hỗ trợ ở phần nghe. Khi có giọng đọc tiếng Trung, hãy chơi lại để luyện nghe thực tế.</div>':''}${s.passed&&s.stage<120?`<div class="bunny-travel" aria-label="Thỏ đi từ cấp ${s.stage} đến cấp ${Math.min(s.stage+1,120)}"><span>${s.stage} ✓</span><div class="travel-rabbit">${bunny()}</div><span>${s.stage+1} ♡</span></div>`:''}<div class="actions-inline result-buttons">${s.passed&&s.stage<120?btn('Chơi cấp tiếp theo →','brief',`data-stage="${s.stage+1}"`):btn('Chơi lại cấp này','brief',`data-stage="${s.stage}"`)}<a class="button ghost" href="#/games/${Math.ceil(current/20)}">Về bản đồ</a></div><p class="xp-note">Chơi lại chỉ nhận thêm XP khi cải thiện thành tích. Phần nói được tự xác nhận, không chấm phát âm tự động.</p></section><section class="game-panel result-skills"><h2>Nhìn lại từng kỹ năng</h2><div class="result-skill-grid">${Object.entries(GC.SKILLS).map(([k,name])=>{const v=s.skills[k];return `<div><span class="skill-token">${skillIcon[k]}</span><div><strong>${name}</strong><p>${k==='speaking'?(v.complete?'✓ Đã tự luyện nói':'Chưa xác nhận'):v.correct+'/'+v.total+' câu đúng'}</p></div><span class="status-badge ${(k==='speaking'?v.complete:v.correct/v.total>=.5)?'complete':'reviewing'}">${k==='speaking'?'Tự đánh giá':v.correct/v.total>=.5?'Đạt':'Cần ôn'}</span></div>`;}).join('')}</div></section><section class="game-panel game-review"><h2>Ghi nhớ từ lượt chơi</h2>${s.questions.filter(q=>s.answers[q.id]?.correct===false).map(q=>`<article><h3>${E(q.prompt)}</h3><p><b>Đáp án:</b> ${E(q.answer)}</p><p>${E(q.explanation)}</p></article>`).join('')||'<p>Bạn đã làm đúng tất cả các câu tính điểm trong lượt này. Thỏ Mây rất tự hào về bạn ♡</p>'}</section>`;
 }
 function renderGuide(){return `<div class="page-title"><a class="back-link" href="#/games/1">← Hành trình Thỏ Mây</a><h1>Chơi vui, học có mục tiêu.</h1><p>Lộ trình 120 cấp do HaloChina biên soạn cho Nga Anh, dùng kho từ và bài học sẵn có, kết hợp nhiều dạng ôn tập.</p></div><article class="game-panel guide-body"><h2>120 cấp được sắp xếp như thế nào?</h2><p>Mỗi HSK có 20 cấp, tổng cộng 6 thế giới. Ngân hàng 5.400 mục từ được chia thành 120 phần theo thứ tự trong đề cương. Mỗi lượt lấy mẫu từ phần tương ứng; chơi lại có thể gặp từ khác. Các mốc 5, 10, 15, 20 có thêm câu và ôn lại từ cũ. Vì đây là lộ trình ôn tập tự biên soạn, hoàn thành một thế giới không tương đương đạt chứng chỉ HSK.</p><h2>Sáu kỹ năng trong một lượt</h2><p>Từ vựng và pinyin; điền cấu trúc ngữ pháp; đọc hiểu câu; nghe câu bằng giọng tổng hợp; gõ chữ Hán hoặc sắp xếp câu; đọc to và tự đánh giá. Mỗi lượt có 12 thử thách, các mốc ôn tập có 16 thử thách. Câu hỏi, ví dụ và đáp án được lấy từ nội dung HaloChina, không sao chép đề thi của ứng dụng khác.</p><h2>Điều kiện mở khóa và điểm thưởng</h2><p>Trả lời đúng ít nhất 80% câu tính điểm, đồng thời đạt ít nhất 50% ở mỗi kỹ năng có chấm điểm và xác nhận đã thực hành nói. Đạt 80% nhận 1 sao; đạt 90% nhận 2 sao; đúng hết nhận 3 sao. Mỗi cấp có 20 XP cơ bản, thêm 10 XP mỗi sao và 10 XP nếu là mốc ôn tập. Chơi lại chỉ được cộng phần XP cải thiện; thất bại không xóa tiến độ.</p><h2>Nghe và nói trên thiết bị</h2><p>Giọng đọc phụ thuộc thiết bị. Nếu không có giọng tiếng Trung, bạn có thể mở văn bản hỗ trợ; kết quả ghi rõ chế độ hỗ trợ và nên luyện lại phần nghe khi có âm thanh. Thu âm chỉ bắt đầu khi bạn chủ động bấm và đồng ý quyền micro; bản ghi chỉ tồn tại trong bộ nhớ trình duyệt và bị xóa khi rời câu hỏi. Có thể đọc to không dùng micro rồi tự xác nhận; website không đưa điểm phát âm tự động.</p><h2>Nguồn tham khảo phương pháp</h2><p>Tham khảo cách sắp xếp bài theo đường đi, xen kẽ nội dung mới và ôn tập từ <a href="https://blog.duolingo.com/new-duolingo-home-screen-design/" target="_blank" rel="noopener noreferrer">Duolingo: thiết kế đường đi học tập</a> và nguyên tắc <a href="https://blog.duolingo.com/spaced-repetition-for-learning/" target="_blank" rel="noopener noreferrer">ôn tập cách quãng</a>. HaloChina tự thiết kế thế giới, nhân vật thỏ, cơ chế sao và nội dung câu hỏi. Bài luyện dùng ngân hàng từ và ngữ pháp có <a href="#/sources">ghi nguồn riêng</a>.</p><h2>Lưu và mang theo tiến độ</h2><p>Cấp đã thắng, sao, XP và lượt chơi dở được lưu tự động trên trình duyệt. Bản sao tiến độ JSON trong mục Tiến độ cũng bao gồm hành trình trò chơi. Nếu trình duyệt không cho lưu dữ liệu, website thông báo “Chưa lưu được”; hãy xuất bản sao trước khi đóng.</p></article>`;}
 async function record(){if(recordingBusy)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#recording-status').textContent='Thiết bị không hỗ trợ thu âm. Bạn có thể đọc to và tự đối chiếu không dùng micro.';return;}
  if('speechSynthesis'in window)window.speechSynthesis.cancel();window.HaloMusic?.cancelSpeech();window.HaloMusic?.hold('recording');recordingBusy=true;const token=++recordingToken,stage=session?.stage,qid=session?.questions[session.index]?.id;$('#recording-status').textContent='Đang chờ quyền micro…';
  try{const obtained=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==recordingToken||route.view!=='game'||session?.stage!==stage||session?.questions[session.index]?.id!==qid){obtained.getTracks().forEach(t=>t.stop());window.HaloMusic?.release('recording');return;}stream=obtained;const chunks=[];recorder=new MediaRecorder(stream);const mime=recorder.mimeType;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{if(token===recordingToken&&$('#recording-preview')&&chunks.length){if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(new Blob(chunks,{type:mime}));$('#recording-preview').innerHTML='<label class="input-label">Nghe lại bản ghi của Nga Anh</label><audio controls aria-label="Bản thu của bạn"></audio>';$('#recording-preview audio').src=audioURL;$('#recording-preview audio').addEventListener('play',()=>window.HaloMusic?.hold('recording'));$('#recording-preview audio').addEventListener('pause',()=>window.HaloMusic?.release('recording'));$('#recording-preview audio').addEventListener('ended',()=>window.HaloMusic?.release('recording'));}obtained.getTracks().forEach(t=>t.stop());recordingBusy=false;window.HaloMusic?.release('recording');};recorder.start();$('[data-action="g-record"]').disabled=true;$('[data-action="g-stop-record"]').disabled=false;$('#recording-status').textContent='● Đang thu âm. Bấm Dừng thu sau khi đọc xong (tối đa 60 giây).';setTimeout(()=>{if(token===recordingToken&&recorder?.state==='recording')finishRecording();},60000);
  }catch{recordingBusy=false;stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;window.HaloMusic?.release('recording');if($('#recording-status'))$('#recording-status').textContent='Chưa có quyền micro. Bạn có thể thử lại hoặc đọc to không dùng micro để tự luyện.';}
 }
 function finishRecording(){if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());if($('#recording-status'))$('#recording-status').textContent='Đã thu xong. Nghe lại và tự đối chiếu với câu mẫu.';if($('[data-action="g-record"]'))$('[data-action="g-record"]').disabled=false;if($('[data-action="g-stop-record"]'))$('[data-action="g-stop-record"]').disabled=true;}
 function listen(){const q=session?.questions[session.index];if(!q)return;if(recorder?.state==='recording')finishRecording();else stopRecording();spokenSample=true;app.speak(q.speak||q.passage);if(q.skill==='listening'){$('#listening-support').innerHTML='<details class="listening-fallback"><summary>Không nghe được? Mở văn bản hỗ trợ</summary><div class="fallback-text"></div></details>';$('.listening-fallback').addEventListener('toggle',e=>{if(e.target.open){assisted=true;$('.fallback-text').textContent=q.speak;}});}}
 function afterRender(r){route=r;clearAuto();if(r.view!=='game'||Number(r.id)!==session?.stage)cleanup();
  window.HaloMusic?.setScene(['games','game-result'].includes(r.view)||r.view==='game'&&!!$('.challenge-card'));window.HaloMusic?.mount();
  if(r.view==='games'){
   const heading=$('.journey-heading');if(heading){const jump=document.createElement('button');jump.className='button ghost small jump-to-rabbit';jump.dataset.action='g-go-current';jump.textContent='Đến chỗ Thỏ Mây ↓';heading.after(jump);}
   if(jumpToRabbit){jumpToRabbit=false;requestAnimationFrame(()=>$('.current-stop')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));}
  }
  if(r.view==='library'){
   const hero=$('.hero');if(hero){hero.classList.add('nga-hero');hero.querySelector('.eyebrow').textContent='NGA ANH HỌC TIẾNG TRUNG';hero.querySelector('h1').innerHTML='Mỗi ngày một chút,<br><em>Nga Anh giỏi hơn.</em>';hero.querySelector('.hero-art').innerHTML=bunny();const bottom=hero.querySelector('.hero-bottom');bottom.innerHTML=`<a class="button light" href="#/games/1">Cùng Thỏ Mây chơi nào →</a><span class="hero-small">120 cấp · 6 thế giới HSK</span>`;}
  }
  if(r.view==='progress'){const s=GC.stats(game()),panel=document.createElement('section');panel.className='game-panel game-progress-summary';panel.innerHTML=`<div><span class="pink-eyebrow">HÀNH TRÌNH THỎ MÂY</span><h2>${s.completed}/120 cấp đã thắng · ${s.xp} XP</h2><p>${s.stars}/360 sao · Thỏ đang ở cấp ${s.current}</p></div><a class="button" href="#/games/${Math.ceil(s.current/20)}">Mở trò chơi →</a>`;$('#main').appendChild(panel);}
  if(r.view==='game'&&session){const q=session.questions[session.index],answer=session.answers[q.id];if(answer&&game().autoAdvance)autoTimer=setTimeout(()=>{if(route.view==='game'&&session?.questions[session.index]?.id===q.id)next();},3000);}
  if(r.view==='game'&&session){const q=session.questions[session.index],answer=session.answers[q.id],key=`${session.stage}-${q.id}`;if(answer&&lastFeedbackKey!==key){lastFeedbackKey=key;requestAnimationFrame(()=>{const panel=$('.coaching-panel');if(!panel)return;const rect=panel.getBoundingClientRect();if(rect.bottom>innerHeight-16||rect.top<84)panel.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});panel.focus({preventScroll:true});});}}
  window.HaloMotion?.afterRender();
 }
 function init(a){app=a;app.progress.game=GC.sanitizeProgress(app.progress.game);const mobileLogo=document.createElement('a');mobileLogo.href='#/library/1';mobileLogo.className='mobile-brand-logo';mobileLogo.setAttribute('aria-label','Nga Anh học tiếng Trung — Trang chủ');mobileLogo.innerHTML='<span class="brand-logo-window"><img src="assets/nga-anh-logo.png" alt="Nga Anh học tiếng Trung" width="2000" height="2000"></span>';$('#menu-toggle').after(mobileLogo);document.addEventListener('click',e=>{const b=e.target.closest('[data-action^="g-"]');if(!b)return;const action=b.dataset.action.slice(2),q=session?.questions[session.index];switch(action){
  case 'brief':brief(Number(b.dataset.stage));break;
  case 'start':start(Number(b.dataset.stage));break;
  case 'world':selectedChapter=Number(b.dataset.world);showAll=false;app.render();break;
  case 'go-current':$('#reader-dialog').close();selectedChapter=Math.ceil(GC.unlocked(game())/20);showAll=false;jumpToRabbit=true;location.hash=`#/games/${selectedChapter}`;if(route.view==='games')app.render();break;
  case 'resume':session=loadSession();if(session){window.HaloMusic?.startGame();$('#reader-dialog').close();order=[];spokenSample=false;location.hash=link(session.stage);if(route.view==='game')app.render();}break;
  case 'ask-discard':app.openDialog('Bỏ lượt chơi đang dở?',`<p class="dialog-copy">Lượt đang chơi sẽ được xóa. Cấp đã thắng, sao và XP vẫn được giữ.</p><div class="actions-inline">${btn('Bỏ lượt đang dở','discard','','danger')}${app.button('Giữ lại','close-dialog','','ghost')}</div>`);break;
  case 'discard':cleanup();session=null;saveSession();$('#reader-dialog').close();app.render();break;
  case 'choice':if(q?.type==='choice')accept(b.dataset.option,{assisted:q.skill==='listening'&&assisted});break;
  case 'check-typing':if(q?.type==='typing'){const text=$('#game-typed').value.trim();if(!text){app.toast('Nga Anh thử viết một câu trả lời trước nhé.');break;}accept(text);}break;
  case 'token':if(q?.type==='order'&&!session.answers[q.id]){const id=Number(b.dataset.token);if(!order.includes(id)&&q.tokens.some(t=>t.id===id))order.push(id);app.render();}break;
  case 'untoken':order=order.filter(id=>id!==Number(b.dataset.token));app.render();break;
  case 'check-order':if(q?.type==='order'){if(order.length!==q.tokens.length){app.toast('Hãy dùng đủ các mảnh từ để hoàn thành câu nhé.');break;}accept(order.map(id=>q.tokens.find(t=>t.id===id).text).join(''));}break;
  case 'confirm-spoken':if(!$('#spoken-confirm')?.checked){app.toast('Hãy đọc to và đánh dấu xác nhận đã tự luyện nói.');break;}stopRecording();accept('practiced',{practiced:true});break;
  case 'listen':listen();break;
  case 'record':record();break;
  case 'stop-record':finishRecording();break;
  case 'next':next();break;
 }});
  document.addEventListener('change',e=>{if(e.target.id==='game-show-all'){showAll=e.target.checked;app.render();}if(e.target.id==='game-auto-next'){game().autoAdvance=e.target.checked;app.persist();afterRender(route);}});
  document.addEventListener('submit',e=>{if(e.target.id==='game-write-form'){e.preventDefault();if(session?.questions[session.index]?.type==='typing'&&!session.answers[session.questions[session.index].id]){const value=$('#game-typed').value.trim();if(value)accept(value);}}});
  window.addEventListener('pagehide',()=>{if(session)saveSession();cleanup();});
 }
 window.HaloGame={init,renderMap,renderPlay,renderResult,renderGuide,afterRender,bunny,getActivity:()=>route.view==='game'&&session&&Number(route.id)===session.stage?{key:`game:${session.startedAt}:${session.stage}`,kind:'game',suppressBlur:recordingBusy&&!recorder}:null};
})();
